# CPU 프로파일링 예시: Python 3에서 실행 가능한 코드
cpu_ms = {"hash": 40, "sort": 120, "format": 10}
print(max(cpu_ms, key=cpu_ms.get))

# I/O 프로파일링 예시: Python 3에서 실행 가능한 코드
latency = {"disk": 8, "network": 70, "cpu": 5}
print(max(latency, key=latency.get))

# 화염 그래프(Flame Graph) 예시: Python 3에서 실행 가능한 코드
stacks = {"main;query;decode": 30, "main;render": 10}
for stack, count in stacks.items():
    print(stack, "#" * (count // 10))

# 핫 패스 찾기 예시: Python 3에서 실행 가능한 코드
paths = {"checkout": 5000, "admin": 40, "report": 120}
print(max(paths, key=paths.get))

# 가비지 컬렉션(GC) 예시: Python 3에서 실행 가능한 코드
live = {"session", "cache"}
heap = {"session", "cache", "temp"}
garbage = heap - live
print(garbage)

# GC 종류(Mark-Sweep/G1/ZGC) 예시: Python 3에서 실행 가능한 코드
collectors = {"Mark-Sweep": "simple", "G1": "region", "ZGC": "low-latency"}
print(collectors["G1"])

# 약한 참조/소프트 참조 예시: Python 3에서 실행 가능한 코드
cache = {"image": "weak-reference"}
memory_low = True
if memory_low:
    cache.pop("image", None)
print(cache)

# CPU 캐시 계층 예시: Python 3에서 실행 가능한 코드
latency = {"L1": 1, "L2": 4, "RAM": 100}
print(min(latency, key=latency.get))

# 캐싱 패턴 심화(캐시 웜업) 예시: Python 3에서 실행 가능한 코드
cache = {}
popular = ["home", "ranking"]
for key in popular:
    cache[key] = f"data:{key}"
print(cache)

# 읽기 최적화 뷰 예시: Python 3에서 실행 가능한 코드
view = {"order_id": 1, "customer": "Kim", "total": 5000}
print(view["total"])

# 역인덱스 예시: Python 3에서 실행 가능한 코드
index = {"cache": [1, 3], "query": [2]}
print(index["cache"])

# CDN 최적화 예시: Python 3에서 실행 가능한 코드
asset = {"ttl": 3600, "compressed": True}
print(asset["ttl"] > 0 and asset["compressed"])

# JVM 튜닝 예시: Python 3에서 실행 가능한 코드
jvm = {"heap_gb": 4, "gc": "G1"}
print(jvm["gc"], jvm["heap_gb"])

# 스레드 덤프 분석 예시: Python 3에서 실행 가능한 코드
threads = {"t1": "RUNNABLE", "t2": "WAITING"}
print([t for t, s in threads.items() if s == "WAITING"])

# 힙 덤프 분석 예시: Python 3에서 실행 가능한 코드
objects = {"bytearray": 120, "session": 30, "cache": 80}
print(max(objects, key=objects.get))

# 인덱스 미스(Index Miss) 탐지 예시: Python 3에서 실행 가능한 코드
plan = {"scan": "seq", "rows": 50000}
print(plan["scan"] == "seq" and plan["rows"] > 10000)

# 디스크 I/O 최적화 예시: Python 3에서 실행 가능한 코드
reads = {"random": 500, "sequential": 50}
print(reads["random"] > reads["sequential"])

# 소켓 최적화 예시: Python 3에서 실행 가능한 코드
socket_opts = {"keepalive": True, "timeout": 3}
print(socket_opts["keepalive"])

# 성능 테스트 시나리오 예시: Python 3에서 실행 가능한 코드
scenario = {"login": 0.2, "search": 0.6, "checkout": 0.2}
print(sum(scenario.values()))

# 클라이언트 사이드 성능 측정 예시: Python 3에서 실행 가능한 코드
metrics = {"lcp": 1800, "inp": 120, "cls": 0.04}
print(metrics["lcp"] < 2500 and metrics["inp"] < 200)
